import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.DCVnL8g5.js";const k=JSON.parse('{"title":"Agentes y forwarding","description":"","frontmatter":{},"headers":[],"relativePath":"devops/ssh/03-agentes-y-forwarding.md","filePath":"devops/ssh/03-agentes-y-forwarding.md","lastUpdated":1789040978000,"isDraft":false}'),t={name:"devops/ssh/03-agentes-y-forwarding.md"};function l(o,s,h,p,r,d){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="agentes-y-forwarding" tabindex="-1">Agentes y forwarding <a class="header-anchor" href="#agentes-y-forwarding" aria-label="Permalink to &quot;Agentes y forwarding&quot;">​</a></h1><p>El agente SSH guarda claves descifradas en memoria para no teclear la passphrase en cada conexion. El agent forwarding permite usar tu clave desde un salto intermedio <strong>sin copiar la privada</strong> al bastion — con matices de seguridad.</p><h2 id="ssh-agent" tabindex="-1">ssh-agent <a class="header-anchor" href="#ssh-agent" aria-label="Permalink to &quot;ssh-agent&quot;">​</a></h2><h3 id="linux-macos" tabindex="-1">Linux / macOS <a class="header-anchor" href="#linux-macos" aria-label="Permalink to &quot;Linux / macOS&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">eval</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre></div><p>En macOS, el Keychain puede persistir:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apple-use-keychain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519</span></span></code></pre></div><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>OpenSSH incluye el servicio agente:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">agent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Set-Service</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">StartupType Manual</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">agent</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ssh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">add $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">USERPROFILE\\.ssh\\id_ed25519</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ssh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">add </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span></span></code></pre></div><p>En <code>~/.ssh/config</code>:</p><div class="language-ssh-config vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ssh-config</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Host</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> *</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AddKeysToAgent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> yes</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  IdentityFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ~/.ssh/id_ed25519</span></span></code></pre></div><h2 id="agent-forwarding-forwardagent" tabindex="-1">Agent forwarding (<code>ForwardAgent</code>) <a class="header-anchor" href="#agent-forwarding-forwardagent" aria-label="Permalink to &quot;Agent forwarding (\`ForwardAgent\`)&quot;">​</a></h2><p>Flujo:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tu laptop --(clave en agente)--&gt; bastion --(usa tu agente)--&gt; host interno</span></span></code></pre></div><p>La privada <strong>no</strong> se copia al bastion; el bastion pregunta a tu agente local.</p><p>Activacion puntual:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ops@bastion.ejemplo.com</span></span></code></pre></div><p>O en config (solo hosts de confianza):</p><div class="language-ssh-config vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ssh-config</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Host</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bastion</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  HostName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bastion.ejemplo.com</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ops</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ForwardAgent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> yes</span></span></code></pre></div><h3 id="riesgo" tabindex="-1">Riesgo <a class="header-anchor" href="#riesgo" aria-label="Permalink to &quot;Riesgo&quot;">​</a></h3><p>Si alguien con root en el bastion accede a tu socket de agente mientras tu sesion esta abierta, puede usar tus claves. Por eso:</p><ul><li>Activa <code>-A</code> solo cuando haga falta.</li><li>Prefiere <code>ProxyJump</code> sin forwarding cuando baste para llegar al destino.</li><li>No uses forwarding hacia maquinas compartidas o poco confiables.</li></ul><h2 id="alternativa-mas-segura-proxyjump" tabindex="-1">Alternativa mas segura: ProxyJump <a class="header-anchor" href="#alternativa-mas-segura-proxyjump" aria-label="Permalink to &quot;Alternativa mas segura: ProxyJump&quot;">​</a></h2><p>Para &quot;entrar al interno a traves del bastion&quot;, normalmente <strong>no</strong> necesitas <code>-A</code>:</p><div class="language-ssh-config vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ssh-config</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Host</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> app-1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  HostName</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0.2.15</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deploy</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ProxyJump</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bastion</span></span></code></pre></div><p>Aqui la autenticacion al host interno la hace tu cliente local, no el bastion.</p><p>Usa forwarding cuando en el bastion debas, por ejemplo, <code>git clone</code> hacia un remoto que solo confia en tu clave.</p><h2 id="x11-y-otros-forwardings" tabindex="-1">X11 y otros forwardings <a class="header-anchor" href="#x11-y-otros-forwardings" aria-label="Permalink to &quot;X11 y otros forwardings&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usuario@host</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # X11 (Linux)</span></span></code></pre></div><p>Menos habitual hoy; para GUIs remotas suele preferirse RDP/VNC o herramientas dedicadas. Los tunnels TCP (capitulo 4) cubren el 90% de los casos (DB, paneles, APIs).</p><h2 id="comprobar-el-agente-en-remoto" tabindex="-1">Comprobar el agente en remoto <a class="header-anchor" href="#comprobar-el-agente-en-remoto" aria-label="Permalink to &quot;Comprobar el agente en remoto&quot;">​</a></h2><p>Tras <code>ssh -A bastion</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SSH_AUTH_SOCK</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span></span></code></pre></div><p>Si <code>SSH_AUTH_SOCK</code> esta vacio, el forwarding no llego.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Dejar <code>ForwardAgent yes</code> en <code>Host *</code>.</li><li>Copiar la clave privada al bastion &quot;para ir mas comodo&quot;.</li><li>Asumir que <code>ProxyJump</code> y <code>-A</code> son lo mismo.</li><li>Olvidar <code>ssh-add</code> tras reiniciar (agente vacio).</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas practicas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas practicas&quot;">​</a></h2><ul><li>Passphrase + agente en local; nunca privadas sin proteger.</li><li><code>ProxyJump</code> por defecto; <code>-A</code> excepcional y temporal.</li><li>CI/CD: usar deploy keys o OIDC, no el agente de tu laptop.</li><li>Revisar <code>ssh-add -l</code> antes de sesiones sensibles.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Anade tu clave al agente y lista huellas con <code>ssh-add -l</code>.</li><li>Conecta a un bastion <strong>sin</strong> <code>-A</code> usando <code>ProxyJump</code> a un host interno (o simulado).</li><li>Prueba una sesion con <code>-A</code> y comprueba <code>ssh-add -l</code> en el bastion; luego desconecta.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continua con <a href="./04-scp-sftp-y-tunnels">SCP SFTP y tunnels</a>.</p>`,43)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
